import kotlin.math.*
import kotlin.io.*

const val EPS = 1e-6
const val PI = acos(-1.0)

data class Point(var x: Double = 0.0, var y: Double = 0.0) {
    operator fun plus(other: Point) = Point(x + other.x, y + other.y)
    operator fun minus(other: Point) = Point(x - other.x, y - other.y)
    operator fun times(scale: Double) = Point(x * scale, y * scale)
    operator fun div(scale: Double) = Point(x / scale, y / scale)

    fun rot90() = Point(-y, x)

    override fun toString(): String {
        val xs = if (abs(x) < EPS) 0.0 else x
        val ys = if (abs(y) < EPS) 0.0 else y
        return "($xs,$ys)"
    }
}

typealias Vec = Point

fun PtoV(a: Point, b: Point): Point = Point(b.x - a.x, b.y - a.y)

fun dMult(a: Point, b: Point): Double = a.x * b.x + a.y * b.y

fun xMult(a: Point, b: Point): Double = a.x * b.y - a.y * b.x

fun VecMod(a: Point): Double = sqrt(dMult(a, a))

fun VecMod2(a: Point): Double = dMult(a, a)

fun Corner2V(a: Point, b: Point): Double {
    val dot = dMult(a, b)
    val modA = VecMod(a)
    val modB = VecMod(b)
    if (modA < EPS || modB < EPS) return 0.0
    val cosAngle = dot / (modA * modB)
    // Clamp to [-1, 1] to avoid NaN due to floating point errors
    val clampedCos = cosAngle.coerceIn(-1.0, 1.0)
    return abs(acos(clampedCos))
}

fun VecUnit(a: Point): Point {
    val mod = VecMod(a)
    if (mod < EPS) return Point(0.0, 0.0)
    return a / mod
}

fun VRotate(v: Point, alph: Double): Point {
    val sa = sin(alph)
    val ca = cos(alph)
    return Point(v.x * ca - v.y * sa, v.x * sa + v.y * ca)
}

fun PRotate(p: Point, o: Point, alph: Double): Point {
    return o + VRotate(PtoV(o, p), alph)
}

fun GetVV(v: Point): Point {
    return VRotate(v, PI / 2)
}

fun ShadowPOnLine(p: Point, a: Point, b: Point): Point {
    val ab = PtoV(a, b)
    val ap = PtoV(a, p)
    val abMod = VecMod(ab)
    if (abMod < EPS) return a
    val projLen = dMult(ab, ap) / abMod
    val unitAb = VecUnit(ab)
    return a + unitAb * projLen
}

fun LineCrossCircle(a: Point, b: Point, o: Point, r: Double): List<Point> {
    val ret = mutableListOf<Point>()
    val t = ShadowPOnLine(o, a, b)
    val ot = PtoV(o, t)
    val otMod = VecMod(ot)

    if (otMod - r > EPS) return ret

    if (abs(otMod - r) < EPS) {
        ret.add(t)
        return ret
    }

    val lr = sqrt(r * r - VecMod2(ot))
    val ta = t + VecUnit(PtoV(t, a)) * lr
    val tb = t + VecUnit(PtoV(t, b)) * lr
    ret.add(ta)
    ret.add(tb)
    return ret
}

fun PointTangentCircle(p: Point, o: Point, r: Double): List<Point> {
    val ret = mutableListOf<Point>()
    val po = PtoV(p, o)
    val x2 = VecMod2(po)

    if (r <= EPS) {
        ret.add(o)
        ret.add(o)
        return ret
    }

    val d2 = x2 - r * r
    if (d2 < -EPS) return ret

    val d2Clamped = max(d2, 0.0)
    val q1 = o + po * (r * r / x2)
    val q2 = po.rot90() * (-r * sqrt(d2Clamped) / x2)

    ret.add(q1 - q2)
    ret.add(q1 + q2)
    return ret
}

fun POnSeg(p: Point, a: Point, b: Point): Boolean {
    if (abs(xMult(PtoV(a, b), PtoV(a, p))) > EPS) return false
    if (min(a.x, b.x) > p.x || p.x > max(a.x, b.x)) return false
    if (min(a.y, b.y) > p.y || p.y > max(a.y, b.y)) return false
    return true
}

fun PDisLine(p: Point, a: Point, b: Point): Double {
    val shadow = ShadowPOnLine(p, a, b)
    return VecMod(shadow - p)
}

var p: Point = Point()
var s: Point = Point()
var vp: Double = 0.0
var vs: Double = 0.0
var r: Double = 0.0
var sita: Double = 0.0

fun check(t: Double): Boolean {
    val lenOr = VecMod(p)
    if (lenOr < EPS) {
        // If p is at origin, angle is undefined, but movement direction might be defined by velocity? 
        // The original code uses p.x/VecMod(p). If lenOr is 0, this crashes. 
        // Assuming p is not origin or handling gracefully.
        // In the context of the problem, p is likely not origin initially.
        // If lenOr is 0, we can't determine angle from position. 
        // However, the formula `sita + t*vp/len_or` suggests angular velocity.
        // If lenOr is 0, this is undefined. We assume lenOr > 0.
        return false 
    }

    val angle = sita + t * vp / lenOr
    val e = Point(lenOr * cos(angle), lenOr * sin(angle))

    val ccp = LineCrossCircle(s, e, Point(0.0, 0.0), r)

    if (ccp.size != 2 || (!POnSeg(ccp[0], s, e) && !POnSeg(ccp[1], s, e))) {
        return vs * t > VecMod(e - s)
    }

    val ttp1 = PointTangentCircle(s, Point(0.0, 0.0), r)
    if (ttp1.size < 2) return false
    if (PDisLine(ttp1[0], s, e) > PDisLine(ttp1[1], s, e)) {
        // Swap
        val temp = ttp1[0]
        ttp1[0] = ttp1[1]
        ttp1[1] = temp
    }
    val l1 = VecMod(PtoV(s, ttp1[0]))

    val ttp2 = PointTangentCircle(e, Point(0.0, 0.0), r)
    if (ttp2.size < 2) return false
    if (PDisLine(ttp2[0], s, e) > PDisLine(ttp2[1], s, e)) {
        val temp = ttp2[0]
        ttp2[0] = ttp2[1]
        ttp2[1] = temp
    }
    val l2 = VecMod(PtoV(e, ttp2[0]))

    val alph = Corner2V(PtoV(Point(0.0, 0.0), ttp1[0]), PtoV(Point(0.0, 0.0), ttp2[0]))

