        return Point(x + other.x, y + other.y)
    }

    operator fun minus(other: Point): Point {
        return Point(x - other.x, y - other.y)
    }

    operator fun times(val: Double): Point {
        return Point(x * val, y * val)
    }

    operator fun div(val: Double): Point {
        return this * (1.0 / val)
    }

    override fun toString(): String {
        val xx = if (abs(x) < EPS) 0.0 else x
        val yy = if (abs(y) < EPS) 0.0 else y
        return "($xx,$yy)"
    }
}

typealias Vec = Point

fun PtoV(a: Point, b: Point): Vec {
    return Vec(b.x - a.x, b.y - a.y)
}

fun dMult(a: Vec, b: Vec): Double {
    return (a.x * b.x) + (a.y * b.y)
}

fun xMult(a: Vec, b: Vec): Double {
    return a.x * b.y - a.y * b.x
}

fun VecMod(a: Vec): Double {
    return sqrt(dMult(a, a))
}

fun VecMod2(a: Vec): Double {
    return dMult(a, a)
}

fun Corner2V(a: Vec, b: Vec): Double {
    val dot = dMult(a, b)
    val modA = VecMod(a)
    val modB = VecMod(b)
    if (modA == 0.0 || modB == 0.0) return 0.0
    val cosVal = dot / modA / modB
    // Clamp to [-1, 1] to avoid NaN due to floating point errors
    val clampedCos = cosVal.coerceIn(-1.0, 1.0)
    return abs(acos(clampedCos))
}

fun VecUnit(a: Vec): Vec {
    return a / VecMod(a)
}

fun VRotate(v: Vec, alph: Double): Vec {
    val sa = sin(alph)
    val ca = cos(alph)
    return Vec(v.x * ca - v.y * sa, v.x * sa + v.y * ca)
}

fun PRotate(p: Point, o: Point, alph: Double): Point {
    return o + VRotate(PtoV(o, p), alph)
}

fun GetVV(v: Vec): Vec {
    return VRotate(v, PI / 2)
}

fun ShadowPOnLine(p: Point, a: Point, b: Point): Point {
    val ab = PtoV(a, b)
    val ap = PtoV(a, p)
    val abMod = VecMod(ab)
    if (abMod < EPS) return a
    val projLen = dMult(ab, ap) / abMod
    val unitAb = VecUnit(ab)
    return a + unitAb * projLen
}

fun LineCrossCircle(a: Point, b: Point, o: Point, r: Double): List<Point> {
    val ret = mutableListOf<Point>()
    val t = ShadowPOnLine(o, a, b)
    val ot = PtoV(o, t)
    val otMod = VecMod(ot)
    if (otMod - r > EPS) return ret
    if (abs(otMod - r) < EPS) {
        ret.add(t)
        return ret
    }
    val lr = sqrt(r * r - VecMod2(ot))
    val ta = t + VecUnit(PtoV(t, a)) * lr
    val tb = t + VecUnit(PtoV(t, b)) * lr
    ret.add(ta)
    ret.add(tb)
    return ret
}

fun PointTangentCircle(p: Point, o: Point, r: Double): List<Point> {
    val ret = mutableListOf<Point>()
    val po = PtoV(p, o)
    val x2 = VecMod2(po)
    val d2 = x2 - r * r
    if (d2 < -EPS) return ret
    if (r <= EPS) {
        ret.add(o)
        ret.add(o)
        return ret
    }
    val d2Clamped = max(d2, 0.0)
    val q1 = o + po * (r * r / x2)
    val q2 = po.rot90() * (-r * sqrt(d2Clamped) / x2)
    ret.add(q1 - q2)
    ret.add(q1 + q2)
    return ret
}

fun POnSeg(p: Point, a: Point, b: Point): Boolean {
    if (abs(xMult(PtoV(a, b), PtoV(a, p))) > EPS) return false
    if (min(a.x, b.x) > p.x || p.x > max(a.x, b.x)) return false
    if (min(a.y, b.y) > p.y || p.y > max(a.y, b.y)) return false
    return true
}

fun PDisLine(p: Point, a: Point, b: Point): Double {
    return VecMod(ShadowPOnLine(p, a, b) - p)
}

var p: Point = Point()
var s: Point = Point()
var vp: Double = 0.0
var vs: Double = 0.0
var r: Double = 0.0
var sita: Double = 0.0

fun check(t: Double): Boolean {
    val lenOr = VecMod(p)
    if (lenOr < EPS) {
        // If p is at origin, angle is undefined, but let's handle it gracefully
        // In the context of the problem, p is likely not at origin or we assume a direction
        // However, the formula uses cos(sita + ...). If lenOr is 0, sita calculation in main might have issues.
        // Assuming lenOr > 0 based on problem constraints usually.
        return false 
    }
    val angle = sita + t * vp / lenOr
    val e = Point(lenOr * cos(angle), lenOr * sin(angle))
    val ccp = LineCrossCircle(s, e, Point(0.0, 0.0), r)
    if (ccp.size != 2 || (!POnSeg(ccp[0], s, e) && !POnSeg(ccp[1], s, e))) {
        return vs * t > VecMod(e - s)
    }
    val ttp1 = PointTangentCircle(s, Point(0.0, 0.0), r)
    if (PDisLine(ttp1[0], s, e) > PDisLine(ttp1[1], s, e)) {
        // Swap
        val temp = ttp1[0]
        ttp1[0] = ttp1[1]
        ttp1[1] = temp
    }
    val l1 = VecMod(PtoV(s, ttp1[0]))

    val ttp2 = PointTangentCircle(e, Point(0.0, 0.0), r)
    if (PDisLine(ttp2[0], s, e) > PDisLine(ttp2[1], s, e)) {
        val temp = ttp2[0]
        ttp2[0] = ttp2[1]
        ttp2[1] = temp
    }
    val l2 = VecMod(PtoV(e, ttp2[0]))

    val alph = Corner2V(PtoV(Point(0.0, 0.0), ttp1[0]), PtoV(Point(0.0, 0.0), ttp2[0]))
    return l1 + l2 + alph * r < vs * t
}

fun main() {
    val scanner = Scanner(System.`in`)
    while (scanner.hasNext()) {
        p = Point(scanner.nextDouble(), scanner.nextDouble())
        vp = scanner.nextDouble()
        s = Point(scanner.nextDouble(), scanner.nextDouble())
        vs = scanner.nextDouble()
        r = scanner.nextDouble()

        val pMod = VecMod(p)
        if (pMod < EPS) {
            // Edge case: p is at origin
            sita = 0.0
        } else {
            sita = acos(p.x / pMod)
            if (p.y < 0) sita = -sita
        }

        var left = 0.0
        var right = 1e10
        while (abs(left - right) > 1e-12) {
            val mid = (left + right) * 0.5
            if (check(mid)) {
                right = mid
            } else {
                left = mid
            }
        }
        println("%.9f".format(left))
    }
}

