	Point t = ShadowPOnLine(o,a,b); // o到直线|ab|的垂足
	Vec ot = PtoV(o,t);
	if(VecMod(ot)-r>eps)return ret; // 没有交点
	if(fabs(VecMod(ot)-r)<eps){ // 如果相切
		ret.push_back(t);
		return ret;
	}
	double lr = sqrt(r*r-VecMod2(ot));
	Vec ta = t + VecUnit(PtoV(t,a))*lr , tb = t + VecUnit(PtoV(t,b))*lr;
	ret.push_back(ta);
	ret.push_back(tb);
	return ret;	
}

